CREATE TABLE focus_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, task_id BIGINT NULL, started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, active_since TIMESTAMP NULL, ended_at TIMESTAMP NULL, duration_seconds INT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', CONSTRAINT fk_focus_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_focus_task FOREIGN KEY(task_id) REFERENCES study_tasks(id) ON DELETE SET NULL, INDEX idx_focus_student_time(student_id,started_at));
